CREATE TABLE IF NOT EXISTS asset_geometries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, geometry_type text NOT NULL DEFAULT 'Point', geometry_json jsonb NOT NULL, crs text NOT NULL DEFAULT 'EPSG:4326', geometry_status text NOT NULL DEFAULT 'Claimed', positional_accuracy_m text, source_type text NOT NULL DEFAULT 'User Supplied', source_reference text, survey_reference text, confidence_score numeric(6,2), captured_at timestamptz, verified_at timestamptz, verifier_reference text, temporal_valid_from timestamptz, temporal_valid_to timestamptz, public_visibility text NOT NULL DEFAULT 'Restricted', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_layers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_code text UNIQUE NOT NULL, layer_name text NOT NULL, description text, authority_reference text, source_url text, data_license text, update_frequency text, layer_status text NOT NULL DEFAULT 'Planned', sensitivity text NOT NULL DEFAULT 'Public', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_layer_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_id uuid NOT NULL REFERENCES gis_layers(id) ON DELETE CASCADE, feature_key text NOT NULL, geometry_json jsonb NOT NULL, properties_json jsonb NOT NULL DEFAULT '{}'::jsonb, crs text NOT NULL DEFAULT 'EPSG:4326', source_reference text, captured_at timestamptz, verified_at timestamptz, confidence_score numeric(6,2), sensitivity text NOT NULL DEFAULT 'Public', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(layer_id,feature_key));
CREATE INDEX IF NOT EXISTS idx_asset_geometries_asset ON asset_geometries(asset_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_layers_code ON gis_layers(layer_code);
CREATE INDEX IF NOT EXISTS idx_gis_features_layer ON gis_layer_features(layer_id,created_at DESC);